// ─────────────────────────────────────────────────────────────────────────────
// Parse & Verify Webhook
// Accepts a HubSpot workflow "Send a webhook" call (or any sender) with:
//   { "feedbackSubmissionId": "…" } / { "submissionIds": [...] }      → read from HubSpot
//   { "contactId": "…", "score": 3, "comment": "…", "submittedAt": "…" } → used as given
// or an array of those. Outside sandbox the shared token must match
// (Authorization: Bearer … or X-Webhook-Token).
// Security note: WEBHOOK_SHARED_TOKEN is read here only because n8n's built-in
// webhook header auth needs a stored credential. It never leaves this node.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const req = $('NPS Submission Webhook').first().json;
let auth = 'skipped (sandbox)';
if (!cfg.sandboxMode && cfg.requireWebhookToken) {
  let crypto; try { crypto = require('crypto'); } catch (e) { throw new Error('Webhook token check needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.'); }
  let expected = ''; try { expected = String($env.WEBHOOK_SHARED_TOKEN || ''); } catch (e) { expected = ''; }
  if (!expected) throw new Error('Rejected: WEBHOOK_SHARED_TOKEN is not set and REQUIRE_WEBHOOK_TOKEN is not false.');
  const h = Object.fromEntries(Object.entries(req.headers || {}).map(([k, v]) => [k.toLowerCase(), String(v)]));
  const got = (h.authorization || '').replace(/^Bearer\s+/i, '') || h['x-webhook-token'] || '';
  const a = crypto.createHash('sha256').update(got).digest(); const b = crypto.createHash('sha256').update(expected).digest();
  if (!got || !crypto.timingSafeEqual(a, b)) throw new Error('Rejected: missing or invalid webhook token.');
  auth = 'verified';
} else if (!cfg.sandboxMode) auth = 'disabled (REQUIRE_WEBHOOK_TOKEN=false)';
let body = req.body; if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const events = Array.isArray(body) ? body : [body || {}];
const ids = []; const inline = []; const ignored = [];
for (const e of events) {
  const sid = e.feedbackSubmissionId ?? e.feedback_submission_id ?? e.submissionId ?? e.hs_object_id ?? (e.subscriptionType ? e.objectId : null);
  for (const id of [sid, ...(Array.isArray(e.submissionIds) ? e.submissionIds : [])].filter((x) => x !== null && x !== undefined)) if (/^\d+$/.test(String(id))) ids.push(String(id));
  if (!sid && (e.contactId || e.contact_id) && e.score !== undefined) {
    inline.push({ submissionId: String(e.id || `inline-${e.contactId || e.contact_id}-${e.submittedAt || e.submitted_at || Date.now()}`), contactId: String(e.contactId || e.contact_id),
      score: Number(e.score), comment: String(e.comment || e.feedback || '').slice(0, 5000), surveyType: String(e.surveyType || e.survey_type || 'NPS'), surveyName: e.surveyName || null,
      submittedAt: e.submittedAt || e.submitted_at || new Date().toISOString() });
  } else if (!sid && !(Array.isArray(e.submissionIds) && e.submissionIds.length)) ignored.push({ reason: 'no_submission_id_or_contact_score', keys: Object.keys(e).slice(0, 8) });
}
return [{ json: { auth, received: events.length, ids: [...new Set(ids)].slice(0, cfg.maxSubmissionsPerRun), inline: inline.slice(0, cfg.maxSubmissionsPerRun), ignored } }];

