// ─────────────────────────────────────────────────────────────────────────────
// Assemble NPS Context
// Submission + contact + primary company, in the same shape as
// "Mock NPS Context". Failed reads leave that context empty.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const base = $('Build Contact Reads').first().json;
const contactsResp = $('HubSpot: Batch Read Contacts').first().json || {};
const companiesResp = $input.first().json || {};
const contacts = new Map((contactsResp.results || []).map((r) => [String(r.id), r]));
const companies = new Map((companiesResp.results || []).map((r) => [String(r.id), r]));
const num = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));
const submissions = base.submissions.map((s) => {
  const ct = s.contactId ? contacts.get(s.contactId) : null; const cp = ct?.properties || {};
  const co = cp.associatedcompanyid ? companies.get(String(cp.associatedcompanyid)) : null; const p = co?.properties || {};
  return { ...s,
    contact: ct ? { id: String(ct.id), name: [cp.firstname, cp.lastname].filter(Boolean).join(' ') || null, email: cp.email || null, jobTitle: cp.jobtitle || null } : { id: s.contactId, name: null, email: null, jobTitle: null },
    company: co ? { id: String(co.id), name: p.name || null, domain: p.domain || null, tier: p[cfg.companyTierProperty] ?? null, arr: num(p[cfg.arrProperty]),
      ownerId: p[cfg.csmOwnerProperty] || (cfg.aeOwnerProperty ? p[cfg.aeOwnerProperty] : null) || null, previousNps: num(p[cfg.lastNpsScoreProperty]),
      retentionStatus: p[cfg.retentionStatusProperty] ?? null, lastSubmissionId: p[cfg.lastNpsSubmissionProperty] ?? null,
      renewalDate: p[cfg.renewalDateProperty] ?? null, lastAlertAt: p[cfg.lastAlertProperty] ?? null, lastAlertTier: p[cfg.lastAlertTierProperty] ?? null } : null };
});
const readErrors = [...base.readErrors, contactsResp.error ? 'contacts_read_failed' : null, companiesResp.error ? 'companies_read_failed' : null].filter(Boolean);
return [{ json: { source: $('Build Submission Reads').first().json.source, submissions, readErrors } }];

// ─────────────────────────────────────────────────────────────────────────────
// Detractor & Enterprise Urgency Analysis
// Per submission:
//  1. Filters: non-NPS surveys, missing score, internal submitters, test
//     accounts, duplicates, submissions older than MAX_SUBMISSION_AGE_HOURS.
//  2. NPS category: detractor 0–DETRACTOR_MAX (6), passive ≤ PASSIVE_MAX (8),
//     promoter otherwise.
//  3. Customer segment: enterprise (tier in ENTERPRISE_TIERS, or contract
//     value ≥ ENTERPRISE_ARR_THRESHOLD), growth (GROWTH_TIERS), else smb.
//  4. Context signals: previous NPS (drop / repeat detractor), renewal within
//     RENEWAL_WINDOW_DAYS, churn language in the comment.
//  5. response_tier:
//       emergency  enterprise detractor (or growth detractor with a churn
//                  signal when ESCALATE_GROWTH_ON_CHURN_SIGNAL=true)
//       high       growth detractor (SMB detractor with SMB_DETRACTOR_ACTION=alert)
//       standard   everything else (SMB detractors get a follow-up task by
//                  default; passives one with PASSIVE_FOLLOW_UP=true)
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { submissions, source, readErrors } = $input.first().json;
const NOW = Date.now(); const H = 3600000;
const lc = (s) => String(s ?? '').trim().toLowerCase();
let store = null; try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const seenMem = (store && store.npsSeen) || {};
const isInternal = (email) => { const d = lc(email).split('@')[1] || ''; return cfg.internalDomains.some((x) => d === x || d.endsWith(`.${x}`)); };
const isTest = (s) => cfg.testNamePatterns.some((p) => lc(s).includes(p));
const isTestDomain = (d) => cfg.testDomains.some((x) => lc(d) === x || lc(d).endsWith(`.${x}`));
const CHURN = cfg.churnKeywords;
const redact = (s) => String(s || '')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
  .replace(/\+?\(?\d[\d\s().-]{6,}\d/g, (m) => (m.replace(/\D/g, '').length >= 7 ? '[phone]' : m))
  .replace(/\s+/g, ' ').trim();

const seenRun = new Set();
const results = submissions.map((s) => {
  const base = { submissionId: s.submissionId, score: s.score, surveyType: s.surveyType, surveyName: s.surveyName, submittedAt: s.submittedAt, contact: s.contact, company: s.company };
  const skip = (reason) => ({ ...base, evaluated: false, skipReason: reason, response_tier: null, should_act: false });
  if (seenRun.has(s.submissionId)) return skip('duplicate_in_run');
  seenRun.add(s.submissionId);
  if (seenMem[s.submissionId] || (s.company?.lastSubmissionId && String(s.company.lastSubmissionId) === s.submissionId)) return skip('already_processed');
  if (!cfg.npsSurveyTypes.includes(lc(s.surveyType))) return skip(`not_nps_survey (${s.surveyType || 'unknown'})`);
  if (s.score === null || !Number.isFinite(s.score) || s.score < 0 || s.score > 10) return skip('missing_or_invalid_score');
  if (isInternal(s.contact?.email)) return skip('internal_submission');
  if (isTest(s.contact?.name) || isTest(s.company?.name) || isTestDomain(s.company?.domain) || isTestDomain(lc(s.contact?.email).split('@')[1])) return skip('test_account');
  const at = Date.parse(s.submittedAt || '');
  if (Number.isFinite(at) && NOW - at > cfg.maxSubmissionAgeHours * H) return skip('older_than_max_age');
  if (!s.company) return skip('no_company');

  const category = s.score <= cfg.detractorMax ? 'detractor' : s.score <= cfg.passiveMax ? 'passive' : 'promoter';
  const tierVal = lc(s.company.tier);
  const segment = cfg.enterpriseTiers.includes(tierVal) || (cfg.enterpriseArrThreshold > 0 && (s.company.arr || 0) >= cfg.enterpriseArrThreshold) ? 'enterprise'
    : cfg.growthTiers.includes(tierVal) ? 'growth' : 'smb';
  const prev = s.company.previousNps;
  const prevCategory = prev === null ? null : prev <= cfg.detractorMax ? 'detractor' : prev <= cfg.passiveMax ? 'passive' : 'promoter';
  const delta = prev === null ? null : s.score - prev;
  const comment = String(s.comment || '');
  const churnHits = CHURN.filter((k) => new RegExp(`(^|[^a-z])${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-z]|$)`, 'i').test(comment));
  const renewalAt = Date.parse(s.company.renewalDate || '');
  const renewalDays = Number.isFinite(renewalAt) ? Math.ceil((renewalAt - NOW) / (24 * H)) : null;
  const signals = [];
  if (category === 'detractor' && prevCategory && prevCategory !== 'detractor') signals.push(`sentiment drop: ${prev} → ${s.score}`);
  if (category === 'detractor' && prevCategory === 'detractor') signals.push(`repeat detractor (previous ${prev})`);
  if (renewalDays !== null && renewalDays >= 0 && renewalDays <= cfg.renewalWindowDays) signals.push(`renewal in ${renewalDays} days`);
  if (churnHits.length) signals.push(`churn language: ${churnHits.slice(0, 3).join(', ')}`);

  let tier = 'standard'; let action = 'none'; let why;
  if (category === 'detractor') {
    if (segment === 'enterprise') { tier = 'emergency'; why = 'Enterprise detractor'; }
    else if (segment === 'growth') {
      if (cfg.escalateGrowthOnChurnSignal && churnHits.length) { tier = 'emergency'; why = 'Growth detractor with churn language'; }
      else { tier = 'high'; why = 'Growth detractor'; }
    } else if (cfg.smbDetractorAction === 'alert') { tier = 'high'; why = 'SMB detractor (SMB_DETRACTOR_ACTION=alert)'; }
    else { tier = 'standard'; why = 'SMB detractor'; action = cfg.smbDetractorAction === 'task' ? 'task' : 'none'; }
  } else if (category === 'passive') { why = 'Passive'; action = cfg.passiveFollowUp ? 'task' : 'none'; }
  else { why = 'Promoter'; }
