  if (tier === 'high') action = 'alert_task';
  return { ...base, evaluated: true, nps_category: category, segment, response_tier: tier, action, reason: why, signals, sentiment_delta: delta, previous_nps: prev,
    renewal_in_days: renewalDays, churn_signals: churnHits, should_act: action !== 'none',
    comment_preview: cfg.includeComment ? (redact(comment).length > cfg.commentChars ? `${redact(comment).slice(0, cfg.commentChars - 1)}…` : redact(comment)) : null };
});
const counts = { submissions: results.length, evaluated: results.filter((r) => r.evaluated).length, skipped: results.filter((r) => !r.evaluated).length,
  detractors: results.filter((r) => r.nps_category === 'detractor').length, passives: results.filter((r) => r.nps_category === 'passive').length, promoters: results.filter((r) => r.nps_category === 'promoter').length,
  emergency: results.filter((r) => r.response_tier === 'emergency').length, high: results.filter((r) => r.response_tier === 'high').length };
return [{ json: { source, readErrors, evaluatedAt: new Date(NOW).toISOString(), counts, results } }];

// ─────────────────────────────────────────────────────────────────────────────
// Plan Response Actions
// Groups submissions by company (two detractors at one account = one huddle),
// applies the per-company cooldown (company LAST_ALERT_PROPERTY + workflow
// memory; a higher tier breaks through) and builds the HubSpot payloads:
//   tasks    one HIGH-priority task per acting company, owner = CSM/AE
//   tickets  one emergency ticket per emergency company (optional)
//   company  retention_status, last_nps_score/category/submission, alert stamp
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const a = $input.first().json;
const RANK = { standard: 0, high: 1, emergency: 2 };
const H = 3600000; const now = Date.now();
let store = null; try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const mem = (store && store.npsCompanyAlerts) || {};
const groups = new Map();
for (const r of a.results.filter((x) => x.evaluated)) { const k = r.company.id; if (!groups.has(k)) groups.set(k, []); groups.get(k).push(r); }
const routeOf = (company) => {
  const R = cfg.emergencyRouting || {};
  const owner = company.ownerId && R.owners && R.owners[String(company.ownerId)];
  return { owner: owner || null, tier: (R.tiers && R.tiers[String(company.tier)]) || null, leadership: R.leadership || null, default: R.default || { name: 'Customer Success' } };
};
const plans = []; const suppressed = [];
for (const [companyId, rs] of groups) {
  const company = rs[0].company;
  const worst = rs.reduce((w, r) => (RANK[r.response_tier] > RANK[w.response_tier] ? r : w), rs[0]);
  const latest = rs.slice().sort((x, y) => String(y.submittedAt).localeCompare(String(x.submittedAt)))[0];
  const acting = rs.filter((r) => r.should_act);
  const tier = worst.response_tier;
  const lastAt = Math.max(Date.parse(company.lastAlertAt || '') || 0, mem[companyId]?.at || 0);
  const lastTier = (mem[companyId]?.at || 0) >= (Date.parse(company.lastAlertAt || '') || 0) ? mem[companyId]?.tier : company.lastAlertTier;
  let cooldown = null;
  if (acting.length && lastAt && now - lastAt < cfg.cooldownHours * H && !(RANK[tier] > (RANK[lastTier] ?? RANK.emergency))) {
    cooldown = `company alerted ${Math.round((now - lastAt) / 60000)} min ago (${lastTier || 'unknown tier'})`;
    suppressed.push({ companyId, company: company.name, tier, submissions: acting.map((r) => r.submissionId), reason: `cooldown: ${cooldown}` });
  }
  plans.push({ companyId, company, tier, latest, submissions: rs, acting: cooldown ? [] : acting, cooldown, route: routeOf(company),
    alert: !cooldown && ['emergency', 'high'].includes(tier), task: !cooldown && acting.length > 0 && cfg.createTasks, ticket: !cooldown && tier === 'emergency' && cfg.createTickets });
}
plans.sort((x, y) => RANK[y.tier] - RANK[x.tier] || (y.company.arr || 0) - (x.company.arr || 0));

const dueIn = { emergency: cfg.taskDueHoursEmergency, high: cfg.taskDueHoursHigh, standard: cfg.taskDueHoursStandard };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const body = (p) => `<p><strong>NPS ${p.tier === 'emergency' ? 'EMERGENCY' : 'follow-up'}: ${esc(p.company.name)}</strong> (${esc(p.company.tier || 'no tier')})</p><ul>${p.acting.map((r) => `<li>Score <strong>${r.score}</strong> (${r.nps_category}) from ${esc(r.contact?.name || 'a contact')}${r.contact?.jobTitle ? `, ${esc(r.contact.jobTitle)}` : ''}${r.signals.length ? ` · ${esc(r.signals.join(' · '))}` : ''}${r.comment_preview ? `<br/>“${esc(r.comment_preview)}”` : ''}</li>`).join('')}</ul><p>Next steps: contact the customer within ${dueIn[p.tier]}h, agree a recovery plan, log the outcome on this task. Created by n8n run ${esc(cfg.runId)}.</p>`;
const ownerOf = (p) => p.company.ownerId || cfg.defaultTaskOwnerId || null;
const taskInputs = plans.filter((p) => p.task).map((p) => ({
  _companyId: p.companyId,
  properties: { hs_task_subject: `${p.tier === 'emergency' ? '🚨 NPS emergency' : 'NPS follow-up'}: ${p.company.name} (score ${p.acting.map((r) => r.score).join(', ')})`.slice(0, 250), hs_task_body: body(p),
    hs_task_status: 'NOT_STARTED', hs_task_priority: p.tier === 'standard' ? 'MEDIUM' : 'HIGH', hs_task_type: 'CALL', hs_timestamp: new Date(now + dueIn[p.tier] * H).toISOString(), ...(ownerOf(p) ? { hubspot_owner_id: String(ownerOf(p)) } : {}) },
  associations: [{ to: { id: p.companyId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 192 }] },
    ...[...new Set(p.acting.map((r) => r.contact?.id).filter(Boolean))].map((id) => ({ to: { id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 204 }] }))],
}));
const ticketInputs = plans.filter((p) => p.ticket).map((p) => ({
  _companyId: p.companyId,
  properties: { subject: `NPS emergency: ${p.company.name}`.slice(0, 250), content: body(p).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 5000),
    hs_pipeline: cfg.ticketPipelineId, hs_pipeline_stage: cfg.ticketStageId, hs_ticket_priority: 'HIGH', ...(ownerOf(p) ? { hubspot_owner_id: String(ownerOf(p)) } : {}) },
  associations: [{ to: { id: p.companyId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 26 }] },
    ...[...new Set(p.acting.map((r) => r.contact?.id).filter(Boolean))].map((id) => ({ to: { id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 16 }] }))],
}));
const companyUpdates = plans.map((p) => {
  const props = {};
  if (cfg.lastNpsScoreProperty) props[cfg.lastNpsScoreProperty] = String(p.latest.score);
  if (cfg.lastNpsCategoryProperty) props[cfg.lastNpsCategoryProperty] = p.latest.nps_category;
  if (cfg.lastNpsSubmissionProperty) props[cfg.lastNpsSubmissionProperty] = p.latest.submissionId;
  if (cfg.retentionStatusProperty && p.submissions.some((r) => r.nps_category === 'detractor') && ['emergency', 'high'].includes(p.tier)) props[cfg.retentionStatusProperty] = cfg.retentionAtRiskValue;
  if (p.alert || p.task) { if (cfg.lastAlertProperty) props[cfg.lastAlertProperty] = new Date(now).toISOString(); if (cfg.lastAlertTierProperty) props[cfg.lastAlertTierProperty] = p.tier; }
  return { id: p.companyId, properties: props };
}).filter((u) => Object.keys(u.properties).length && cfg.updateCompanyProperties);
const strip = (xs) => xs.map(({ _companyId, ...rest }) => rest);
return [{ json: { ...a, plans, suppressed,
  taskBody: { inputs: strip(taskInputs) }, taskCompanies: taskInputs.map((t) => t._companyId),
  ticketBody: { inputs: strip(ticketInputs) }, ticketCompanies: ticketInputs.map((t) => t._companyId),
  companyBody: { inputs: companyUpdates },
