const cfg = $('Config & Safety Gate').first().json.config;
const plan = $('Plan Response Actions').first().json;
const get = (n) => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const t = get('HubSpot: Create Retention Tasks'); const k = get('HubSpot: Create Emergency Tickets'); const c = get('HubSpot: Update Company Properties');
const ids = (resp, companies) => {
  const out = {};
  if (resp && !resp.error && Array.isArray(resp.results)) resp.results.forEach((r, i) => { if (companies[i]) out[companies[i]] = String(r.id); });
  return out;
};
const res = {
  tasks: { attempted: plan.taskCompanies.length, ok: t ? !t.error : null, error: t?.error ? String(t.error.message || t.error).slice(0, 200) : null, byCompany: ids(t, plan.taskCompanies) },
  tickets: { attempted: plan.ticketCompanies.length, ok: k ? !k.error : null, error: k?.error ? String(k.error.message || k.error).slice(0, 200) : null, byCompany: ids(k, plan.ticketCompanies) },
  companies: { attempted: plan.companyBody.inputs.length, ok: c ? !c.error : null, error: c?.error ? String(c.error.message || c.error).slice(0, 200) : null, updated: Array.isArray(c?.results) ? c.results.length : 0 },
};
let store = null; try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
if (store && cfg.executionMode === 'production') {
  store.npsCompanyAlerts = store.npsCompanyAlerts || {}; store.npsSeen = store.npsSeen || {};
  for (const p of plan.plans.filter((x) => x.task && res.tasks.byCompany[x.companyId])) store.npsCompanyAlerts[p.companyId] = { at: Date.now(), tier: p.tier };
  for (const r of plan.results.filter((x) => x.evaluated)) store.npsSeen[r.submissionId] = Date.now();
}
return [{ json: res }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Slack Emergency Alerts
// One Block Kit message per alerting company (emergency → emergency channel,
