//   header, @here (emergency, MENTION_HERE_ON_EMERGENCY), CSM / tier lead /
//   leadership mentions from EMERGENCY_ROUTING, account facts, each detractor
//   with score, signals and redacted comment, huddle instructions with the
//   meeting link (HUDDLE_MEETING_URL_TEMPLATE) and buttons to the company,
//   contact, retention task and ticket in HubSpot.
// Incoming webhooks cannot start a Slack huddle; the message tells responders
// to start one in the channel and links the fallback meeting room.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const plan = $('Plan Response Actions').first().json;
let crm = null; try { crm = $('Collect CRM Results').isExecuted ? $('Collect CRM Results').first().json : null; } catch (e) { crm = null; }
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rec = (type, id) => (cfg.portalId && id ? `https://app.hubspot.com/contacts/${cfg.portalId}/record/${type}/${id}` : null);
const mention = (x) => (x ? (x.slack ? `<@${esc(x.slack)}>` : esc(x.name)) : null);
const money = (n) => (n ? `${cfg.currencySymbol}${Math.round(n).toLocaleString('en-US')}` : '—');
const messages = [];
for (const p of plan.plans.filter((x) => x.alert)) {
