  const meet = cfg.huddleUrlTemplate ? cfg.huddleUrlTemplate.replace('{companyId}', encodeURIComponent(p.companyId)).replace('{companyName}', encodeURIComponent(p.company.name || '')) : null;
  const taskId = crm?.tasks?.byCompany?.[p.companyId]; const ticketId = crm?.tickets?.byCompany?.[p.companyId];
  const firstContact = p.acting.find((r) => r.contact?.id)?.contact;
  const buttons = [
    rec('0-2', p.companyId) && { type: 'button', text: { type: 'plain_text', text: 'Open company' }, url: rec('0-2', p.companyId), ...(em ? { style: 'danger' } : {}) },
    firstContact && rec('0-1', firstContact.id) && { type: 'button', text: { type: 'plain_text', text: 'Open contact' }, url: rec('0-1', firstContact.id) },
    taskId && rec('0-27', taskId) && { type: 'button', text: { type: 'plain_text', text: 'Retention task' }, url: rec('0-27', taskId) },
    ticketId && rec('0-5', ticketId) && { type: 'button', text: { type: 'plain_text', text: 'Emergency ticket' }, url: rec('0-5', ticketId) },
    meet && { type: 'button', text: { type: 'plain_text', text: 'Join huddle room' }, url: meet, style: 'primary' },
  ].filter(Boolean);
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `${em ? '🚨 NPS EMERGENCY' : '⚠️ NPS detractor'}: ${p.company.name || 'Unknown account'}`.slice(0, 150), emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: `${em && cfg.mentionHereOnEmergency ? '<!here> ' : ''}${people.join(' ')} · ${p.acting.length} detractor response${p.acting.length === 1 ? '' : 's'} from a *${esc(p.company.tier || 'unknown')}* account.` } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Tier*\n${esc(p.company.tier || '—')}` }, { type: 'mrkdwn', text: `*Contract value*\n${money(p.company.arr)}` },
      { type: 'mrkdwn', text: `*Renewal*\n${esc(p.company.renewalDate || '—')}` }, { type: 'mrkdwn', text: `*Previous NPS*\n${p.company.previousNps ?? '—'}` },
    ] },
    ...p.acting.slice(0, 5).map((r) => ({ type: 'section', text: { type: 'mrkdwn', text: `*Score ${r.score}/10* · ${esc(r.surveyName || 'NPS')}${cfg.showContactName && r.contact?.name ? ` · ${esc(r.contact.name)}${r.contact.jobTitle ? `, ${esc(r.contact.jobTitle)}` : ''}` : r.contact?.jobTitle ? ` · ${esc(r.contact.jobTitle)}` : ''}${r.signals.length ? `\n${r.signals.map((x) => `• ${esc(x)}`).join('\n')}` : ''}${r.comment_preview ? `\n>${esc(r.comment_preview)}` : ''}`.slice(0, 2900) } })),
  ];
  if (em) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Huddle now:* click *Huddle* in this channel's header${meet ? ', or join the room below' : ''}. Agree an owner, call the customer within ${cfg.taskDueHoursEmergency}h, and log the plan on the retention task.` } });
  if (buttons.length) blocks.push({ type: 'actions', elements: buttons.slice(0, 5) });
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${taskId ? `task ${esc(taskId)} · ` : cfg.writeToHubspot ? '' : 'task not created (write-back off) · '}${ticketId ? `ticket ${esc(ticketId)} · ` : ''}submission ${esc(p.acting.map((r) => r.submissionId).join(', '))} · run ${esc(cfg.runId)}`.slice(0, 2900) }] });
  messages.push({ channel: em ? 'emergency' : 'alerts', companyId: p.companyId, tier: p.tier, body: { text: `${em ? 'NPS EMERGENCY' : 'NPS detractor'}: ${p.company.name} (${p.acting.map((r) => r.score).join(', ')}/10)`, blocks } });
