// ─────────────────────────────────────────────────────────────────────────────
// Collect Slack Results
// Joins Slack responses by index; records alerted companies in workflow
// memory (production executions) for the cooldown.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const msgs = $('Emit Slack Messages').all(); const resp = $input.all();
if (resp.length !== msgs.length) throw new Error(`Slack result mismatch: ${msgs.length} messages vs ${resp.length} responses.`);
const results = msgs.map((m, i) => ({ companyId: m.json.companyId, tier: m.json.tier, channel: m.json.channel, ok: !resp[i].json.error, error: resp[i].json.error ? String(resp[i].json.error.message || resp[i].json.error).slice(0, 200) : null }));
let store = null; try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
if (store && cfg.executionMode === 'production') { store.npsCompanyAlerts = store.npsCompanyAlerts || {}; for (const r of results.filter((x) => x.ok)) store.npsCompanyAlerts[r.companyId] = { at: Date.now(), tier: r.tier }; }
return [{ json: { results, sent: results.filter((r) => r.ok).length, failed: results.filter((r) => !r.ok).length } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Run Summary
// One JSON document for ALERT_WEBHOOK_URL (CS platform, BI, incident tooling):
// counts and per-company responses. No comments or contact data.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const plan = $('Plan Response Actions').first().json;
let crm = null; try { crm = $('Collect CRM Results').isExecuted ? $('Collect CRM Results').first().json : null; } catch (e) { crm = null; }
let sl = null; try { sl = $('Collect Slack Results').isExecuted ? $('Collect Slack Results').first().json : null; } catch (e) { sl = null; }
const acting = plan.plans.filter((p) => p.alert || p.task);
const body = {
  event: 'hubspot.nps_detractor.run', runId: cfg.runId, generatedAt: new Date().toISOString(),
  mode: cfg.sandboxMode ? 'sandbox' : (cfg.sendSlackAlerts || cfg.writeToHubspot) ? 'live' : 'dry_run', counts: plan.counts,
  responses: acting.map((p) => ({ company_id: p.companyId, company: p.company.name, tier: p.tier, segment: p.acting[0]?.segment || null, scores: p.acting.map((r) => r.score), signals: [...new Set(p.acting.flatMap((r) => r.signals))], task_id: crm?.tasks?.byCompany?.[p.companyId] || null, ticket_id: crm?.tickets?.byCompany?.[p.companyId] || null })),
  suppressed: plan.suppressed, slack: sl ? { sent: sl.sent, failed: sl.failed } : null,
};
return [{ json: { body, sendAllowed: cfg.webhookEnabled && (acting.length > 0 || (sl && sl.failed > 0) || cfg.notifyOnEveryRun) } }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path: per-submission category, segment, tier and
// skip reason; per-company actions; suppressions; CRM and Slack results.
// Comments and contact details are excluded.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const one = (n) => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const all = (n) => { try { return $(n).isExecuted ? $(n).all().map((i) => i.json) : []; } catch (e) { return []; } };
const wh = one('Parse & Verify Webhook'); const plan = one('Plan Response Actions'); const an = plan || one('Detractor & Enterprise Urgency Analysis');
const crm = one('Collect CRM Results'); const sl = one('Collect Slack Results'); const sum = all('Webhook: Post Run Summary');
let outcome = 'no_submissions';
if (an) {
  const alerting = plan ? plan.plans.filter((p) => p.alert || p.task).length : 0;
  if (!an.counts.evaluated) outcome = 'no_submissions_to_evaluate';
  else if (!alerting) outcome = plan && plan.suppressed.length ? 'responses_suppressed' : 'no_action_needed';
  else if (cfg.sandboxMode) outcome = 'responses_found_sandbox';
  else if (!cfg.sendSlackAlerts && !cfg.writeToHubspot) outcome = cfg.dryRun ? 'responses_found_dry_run' : 'responses_found_outputs_disabled';
  else if ((sl && sl.failed) || (crm && [crm.tasks, crm.tickets, crm.companies].some((x) => x.ok === false))) outcome = 'responded_with_errors';
  else outcome = 'responded';
}
const status = (list) => (!list.length ? 'not_sent' : list.some((x) => x.error) ? 'failed' : 'sent');
return [{ json: {
  workflow: 'n8n-hubspot-nps-detractor-slack-huddle-provisioner',
  runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, sendSlackAlerts: cfg.sendSlackAlerts, writeToHubspot: cfg.writeToHubspot },
  thresholds: { detractorMax: cfg.detractorMax, passiveMax: cfg.passiveMax, enterpriseTiers: cfg.enterpriseTiers, growthTiers: cfg.growthTiers, enterpriseArrThreshold: cfg.enterpriseArrThreshold, cooldownHours: cfg.cooldownHours, maxSubmissionAgeHours: cfg.maxSubmissionAgeHours },
  source: an ? an.source : (wh ? 'webhook' : null), webhook: wh ? { auth: wh.auth, received: wh.received, ids: wh.ids.length, inline: wh.inline.length, ignored: wh.ignored } : null,
  readErrors: an ? an.readErrors : [], counts: an ? an.counts : null,
  submissions: an ? an.results.map((r) => ({ submissionId: r.submissionId, companyId: r.company?.id || null, score: r.score, category: r.nps_category || null, segment: r.segment || null, tier: r.response_tier, action: r.action || null, skipReason: r.skipReason || null, signals: r.signals || [] })) : [],
  companies: plan ? plan.plans.map((p) => ({ companyId: p.companyId, company: p.company.name, tier: p.tier, alert: p.alert, task: p.task, ticket: p.ticket, cooldown: p.cooldown })) : [],
  suppressed: plan ? plan.suppressed : [],
  hubspot: crm || { tasks: null, tickets: null, companies: null },
  slack: sl ? sl.results : [],
  runSummaryWebhook: status(sum),
} }];
